svg.script:
(function() {
  'use strict';

  // State Dictionary
  var state = {
    activeView: 'sagittal', // 'sagittal', 'superior', 'compartments'
    activeHotspot: null
  };

  // Landmark Data for Dynamic Reading Panel Updates
  var landmarkData = {
    promontory: {
      title: "1. Promontório Sacral (S1)",
      badge: "POSTERIOR · ÂNCORA SACRAL",
      badgeColor: "gold",
      desc: "Projeção anterior da 1ª vértebra sacral (S1). Marca a extremidade posterior da Linha Terminal e a margem posterior do Estreito Superior da pelve."
    },
    arcuate: {
      title: "2. Linha Arqueada do Ílio",
      badge: "LATERAL · CORPO DO ÍLIO",
      badgeColor: "pink",
      desc: "Crista suave contínua na face interna do ílio que se estende obliquamente para baixo e para frente, conectando o sacro ao púbis."
    },
    pecten: {
      title: "3. Pecten do Púbis (Linha Pectínea)",
      badge: "ANTERO-LATERAL · RAMO PÚBICO",
      badgeColor: "pink",
      desc: "Crista agulhada no ramo superior do púbis. Dá inserção ao ligamento pectíneo (de Cooper) e forma a porção anterior da linha inominada."
    },
    symphysis: {
      title: "4. Borda Superior da Sínfise Púbica",
      badge: "ANTERIOR · CONVERGÊNCIA MEDIAL",
      badgeColor: "teal",
      desc: "Ponto de encontro anterior mediano de ambos os ossos púbicos. A borda superior da sínfise fecha o anel tridimensional do estreito superior."
    }
  };

  // Element References
  var tabSagittal = document.getElementById('a12p8h-tab-sagittal');
  var tabSuperior = document.getElementById('a12p8h-tab-superior');
  var tabCompartments = document.getElementById('a12p8h-tab-compartments');

  var viewSagittal = document.getElementById('a12p8h-view-sagittal');
  var viewSuperior = document.getElementById('a12p8h-view-superior');
  var viewCompartments = document.getElementById('a12p8h-view-compartments');

  var panelHeadTitle = document.getElementById('a12p8h-panel-head-title');
  var panelBadgeText = document.getElementById('a12p8h-panel-badge-text');
  var panelDesc = document.getElementById('a12p8h-panel-desc');

  // Helper: Switch Active Tab and Visible View
  function switchView(viewName) {
    state.activeView = viewName;

    // Reset Tabs styling
    tabSagittal.classList.remove('a12p8h-active');
    tabSuperior.classList.remove('a12p8h-active');
    tabCompartments.classList.remove('a12p8h-active');

    // Hide all views
    viewSagittal.classList.add('a12p8h-hidden');
    viewSuperior.classList.add('a12p8h-hidden');
    viewCompartments.classList.add('a12p8h-hidden');

    if (viewName === 'sagittal') {
      tabSagittal.classList.add('a12p8h-active');
      viewSagittal.classList.remove('a12p8h-hidden');
      updatePanelDefault("Perfil Sagital 3D (Visão de Níveis)", "FRONTEIRA 3D CONTINUA", "No perfil sagital, percebe-se claramente a inclinação de 55° a 60° da Linha Terminal. O plano que ela define separa a cavidade abdominal (Pelve Maior) da cavidade pélvica obstétrica (Pelve Menor).");
    } else if (viewName === 'superior') {
      tabSuperior.classList.add('a12p8h-active');
      viewSuperior.classList.remove('a12p8h-hidden');
      updatePanelDefault("Estreito Superior (Anel Fechado)", "VISÃO SUPERIOR DO ANEL", "Na visão superior, a Linha Terminal desenha um anel fechado incompressível. Os diâmetros transverso (~13cm) e anteroposterior (~11cm) definem o espaço disponível para o feto.");
    } else if (viewName === 'compartments') {
      tabCompartments.classList.add('a12p8h-active');
      viewCompartments.classList.remove('a12p8h-hidden');
      updatePanelDefault("Comparativo de Compartimentos", "ANÁLISE COMPARATIVA", "A Pelve Maior suporta vísceras abdominais e não oferece resistência. A Pelve Menor forma o canal de parto rígido e contém os órgãos pélvicos urogenitais.");
    }
  }

  function updatePanelDefault(title, badge, text) {
    if (panelHeadTitle) panelHeadTitle.textContent = title;
    if (panelBadgeText) panelBadgeText.textContent = badge;
    if (panelDesc) {
      panelDesc.innerHTML = '<tspan x="0" dy="0">' + text + '</tspan>';
    }
  }

  function updatePanelLandmark(key) {
    var data = landmarkData[key];
    if (!data) return;

    if (panelHeadTitle) panelHeadTitle.textContent = data.title;
    if (panelBadgeText) panelBadgeText.textContent = data.badge;
    if (panelDesc) {
      panelDesc.innerHTML = '<tspan x="0" dy="0" font-weight="700" fill="#ffb703">' + data.title + '</tspan>' +
                            '<tspan x="0" dy="22">' + data.desc + '</tspan>';
    }
  }

  // Event Listeners for Tabs
  if (tabSagittal) {
    tabSagittal.addEventListener('click', function() { switchView('sagittal'); });
    tabSagittal.addEventListener('keydown', function(e) { if(e.key==='Enter'||e.key===' ') switchView('sagittal'); });
  }
  if (tabSuperior) {
    tabSuperior.addEventListener('click', function() { switchView('superior'); });
    tabSuperior.addEventListener('keydown', function(e) { if(e.key==='Enter'||e.key===' ') switchView('superior'); });
  }
  if (tabCompartments) {
    tabCompartments.addEventListener('click', function() { switchView('compartments'); });
    tabCompartments.addEventListener('keydown', function(e) { if(e.key==='Enter'||e.key===' ') switchView('compartments'); });
  }

  // Bind Hotspots
  var hsPromontory = document.getElementById('a12p8h-hs-promontory');
  var hsArcuate = document.getElementById('a12p8h-hs-arcuate');
  var hsPecten = document.getElementById('a12p8h-hs-pecten');
  var hsSymphysis = document.getElementById('a12p8h-hs-symphysis');

  var hsSupProm = document.getElementById('a12p8h-hs-sup-prom');
  var hsSupArcLeft = document.getElementById('a12p8h-hs-sup-arcuate-left');
  var hsSupArcRight = document.getElementById('a12p8h-hs-sup-arcuate-right');
  var hsSupSymph = document.getElementById('a12p8h-hs-sup-symphysis');

  function bindLandmark(el, key) {
    if (!el) return;
    el.addEventListener('click', function() { updatePanelLandmark(key); });
    el.addEventListener('mouseover', function() { updatePanelLandmark(key); });
  }

  bindLandmark(hsPromontory, 'promontory');
  bindLandmark(hsArcuate, 'arcuate');
  bindLandmark(hsPecten, 'pecten');
  bindLandmark(hsSymphysis, 'symphysis');

  bindLandmark(hsSupProm, 'promontory');
  bindLandmark(hsSupArcLeft, 'arcuate');
  bindLandmark(hsSupArcRight, 'arcuate');
  bindLandmark(hsSupSymph, 'symphysis');

})();
